const body = $json.body ?? $json;
return [{
  json: {
    orderId: String(body.orderId ?? '').trim().toUpperCase(),
    email: String(body.email ?? '').trim().toLowerCase()
  }
}];

const request = $json;
const demoOrders = [
  { orderId: 'VAN-1001', email: 'ana@example.com', status: 'processing', updatedAt: '2026-07-30' },
  { orderId: 'VAN-1002', email: 'luis@example.com', status: 'shipped', updatedAt: '2026-07-29' }
];
const order = demoOrders.find(
  item => item.orderId === request.orderId && item.email === request.email
);
if (!order) {
  return [{
    json: {
      ok: false,
      found: false,
      message: 'No matching demo order was found. Do not reveal whether an order ID exists without identity verification.'
    }
  }];
}
return [{
  json: {
    ok: true,
    found: true,
    orderId: order.orderId,
    status: order.status,
    updatedAt: order.updatedAt
  }
}];
